#!/usr/bin/env node

/**
 * Postal Code Data Validator
 *
 * Validates the structure and integrity of postal code JSON files
 * generated by the GeoNames converter.
 *
 * Usage:
 *   node scripts/validate-postal-data.js <json_file> [country_code]
 *
 * Examples:
 *   node scripts/validate-postal-data.js data/postal-codes-fr.json FR
 *   node scripts/validate-postal-data.js data/postal-codes-de.json DE
 */

const fs = require('fs');

function validatePostalData(jsonFile, countryCode = 'XX') {
    console.error(`🔍 Validating ${jsonFile} for country ${countryCode}...`);

    if (!fs.existsSync(jsonFile)) {
        console.error(`❌ Error: File '${jsonFile}' does not exist`);
        process.exit(1);
    }

    try {
        const data = JSON.parse(fs.readFileSync(jsonFile, 'utf8'));
        const postalCodes = Object.keys(data);

        console.error(`📊 Found ${postalCodes.length} postal codes to validate`);

        let errors = [];
        let warnings = [];
        let stats = {
            total: postalCodes.length,
            validCoords: 0,
            validPostalFormat: 0,
            hasMunicipality: 0,
            hasProvince: 0,
            coordRanges: { minLat: 90, maxLat: -90, minLon: 180, maxLon: -180 }
        };

        // Country-specific validation patterns
        const patterns = {
            ES: /^\d{5}$/,
            FR: /^\d{5}(\s+[A-Z\s]+)?$/, // Allow CEDEX and other suffixes
            DE: /^\d{5}$/,
            IT: /^\d{5}$/,
            PT: /^\d{4}-\d{3}$|^\d{7}$/,
            XX: /.*/ // Any format for generic validation
        };

        const postalPattern = patterns[countryCode] || patterns.XX;

        // Validate each postal code entry
        postalCodes.forEach(postalCode => {
            const entry = data[postalCode];

            // Check postal code format
            if (!postalPattern.test(postalCode)) {
                errors.push(`Invalid postal code format: ${postalCode}`);
            } else {
                stats.validPostalFormat++;
            }

            // Check coordinates
            const { lat, lon } = entry;
            if (typeof lat !== 'number' || typeof lon !== 'number') {
                errors.push(`Invalid coordinate types for ${postalCode}: lat=${typeof lat}, lon=${typeof lon}`);
            } else if (isNaN(lat) || isNaN(lon)) {
                errors.push(`NaN coordinates for ${postalCode}: lat=${lat}, lon=${lon}`);
            } else if (lat < -90 || lat > 90) {
                errors.push(`Latitude out of range for ${postalCode}: ${lat}`);
            } else if (lon < -180 || lon > 180) {
                errors.push(`Longitude out of range for ${postalCode}: ${lon}`);
            } else {
                stats.validCoords++;
                stats.coordRanges.minLat = Math.min(stats.coordRanges.minLat, lat);
                stats.coordRanges.maxLat = Math.max(stats.coordRanges.maxLat, lat);
                stats.coordRanges.minLon = Math.min(stats.coordRanges.minLon, lon);
                stats.coordRanges.maxLon = Math.max(stats.coordRanges.maxLon, lon);
            }

            // Check municipality
            if (!entry.municipality || typeof entry.municipality !== 'string' || entry.municipality.trim().length === 0) {
                warnings.push(`Missing or invalid municipality for ${postalCode}`);
            } else {
                stats.hasMunicipality++;
            }

            // Check province
            if (!entry.province || typeof entry.province !== 'string' || entry.province.trim().length === 0) {
                warnings.push(`Missing or invalid province for ${postalCode}`);
            } else {
                stats.hasProvince++;
            }
        });

        // Print results
        console.error(`\n✅ Validation Results:`);
        console.error(`   Total entries: ${stats.total}`);
        console.error(`   Valid postal codes: ${stats.validPostalFormat} (${((stats.validPostalFormat/stats.total)*100).toFixed(1)}%)`);
        console.error(`   Valid coordinates: ${stats.validCoords} (${((stats.validCoords/stats.total)*100).toFixed(1)}%)`);
        console.error(`   Has municipality: ${stats.hasMunicipality} (${((stats.hasMunicipality/stats.total)*100).toFixed(1)}%)`);
        console.error(`   Has province: ${stats.hasProvince} (${((stats.hasProvince/stats.total)*100).toFixed(1)}%)`);

        console.error(`\n📍 Coordinate Ranges:`);
        console.error(`   Latitude: ${stats.coordRanges.minLat.toFixed(4)} to ${stats.coordRanges.maxLat.toFixed(4)}`);
        console.error(`   Longitude: ${stats.coordRanges.minLon.toFixed(4)} to ${stats.coordRanges.maxLon.toFixed(4)}`);

        if (errors.length > 0) {
            console.error(`\n❌ Errors (${errors.length}):`);
            errors.slice(0, 10).forEach(error => console.error(`   - ${error}`));
            if (errors.length > 10) {
                console.error(`   ... and ${errors.length - 10} more errors`);
            }
        }

        if (warnings.length > 0) {
            console.error(`\n⚠️  Warnings (${warnings.length}):`);
            warnings.slice(0, 5).forEach(warning => console.error(`   - ${warning}`));
            if (warnings.length > 5) {
                console.error(`   ... and ${warnings.length - 5} more warnings`);
            }
        }

        // Overall assessment
        const errorRate = errors.length / stats.total;
        const hasErrors = errors.length > 0;
        const hasManyWarnings = warnings.length > stats.total * 0.01; // More than 1% warnings

        console.error(`\n🎯 Overall Assessment:`);
        if (!hasErrors && !hasManyWarnings) {
            console.error(`   ✅ EXCELLENT: Data appears to be in excellent condition`);
        } else if (!hasErrors && hasManyWarnings) {
            console.error(`   ⚠️  GOOD: Data is valid but has some missing fields`);
        } else if (hasErrors && errorRate < 0.01) {
            console.error(`   ⚠️  ACCEPTABLE: Few errors (${(errorRate*100).toFixed(2)}% error rate)`);
        } else {
            console.error(`   ❌ POOR: Significant data quality issues (${(errorRate*100).toFixed(2)}% error rate)`);
        }

        // Sample entries
        console.error(`\n📋 Sample Entries:`);
        const samples = postalCodes.slice(0, 3);
        samples.forEach(code => {
            const entry = data[code];
            console.error(`   ${code}: ${entry.municipality || 'N/A'} (${entry.province || 'N/A'}) @ ${entry.lat}, ${entry.lon}`);
        });

        return {
            isValid: !hasErrors,
            stats,
            errorCount: errors.length,
            warningCount: warnings.length
        };

    } catch (error) {
        console.error(`❌ Error reading/parsing JSON file: ${error.message}`);
        process.exit(1);
    }
}

function main() {
    const args = process.argv.slice(2);

    if (args.length < 1 || args.length > 2) {
        console.error('Usage: node scripts/validate-postal-data.js <json_file> [country_code]');
        console.error('Examples:');
        console.error('  node scripts/validate-postal-data.js data/postal-codes-fr.json FR');
        console.error('  node scripts/validate-postal-data.js data/postal-codes-de.json DE');
        process.exit(1);
    }

    const jsonFile = args[0];
    const countryCode = args[1] || 'XX';

    validatePostalData(jsonFile, countryCode);
}

if (require.main === module) {
    main();
}

module.exports = { validatePostalData };